def passthrough(f):
    @functools.wraps(f)
    def method(*args, **kwargs):
        return f(*args, **kwargs)

    return method

@functools.wraps(f)
def method(*args, **kwargs):
    return f(*args, **kwargs)

def create_dependency(name: str):
    def fun(deps: DepList):
        deps.append(name)

    return Depends(fun)

